31	/**
32	 * Stateful wrapper used by interaction stories to mirror parent-driven refresh
33	 * behaviour after submit by updating the `responses` prop in-memory.
34	 */
35	const StatefulResponsesForm = (args: Story['args']) => {
36	    const [responses, setResponses] = useState(args.responses ?? []);
37	
38	    return (
39	        <ResponsesForm
40	            gameId={args.gameId ?? 0}
41	            gameDate={args.gameDate ?? ''}
42	            responses={responses}
43	            submitResponse={async (payload) => {
44	                const result = await (args.submitResponse?.(payload) ?? Promise.resolve(null));
45	                setResponses((previous) => previous.map((row) => (
46	                    row.playerId === payload.playerId ?
47	                        {
48	                            ...row,
49	                            response: payload.response,
50	                            goalie: payload.goalie,
51	                            comment: payload.comment,
52	                        } :
53	                        row
54	                )));
55	                return result;
56	            }}
57	        />
58	    );
59	};
