import { chromium } from 'playwright';

const url = 'http://localhost:6006/iframe.html?id=admin-responsesform--render&viewMode=story';
const widths = [1600, 1200, 900, 600, 375];

const browser = await chromium.launch();
for (const width of widths) {
    const page = await browser.newPage({ viewport: { width, height: 900 } });
    await page.goto(url, { waitUntil: 'networkidle' });
    await page.waitForSelector('text=Search players', { timeout: 15000 });
    await page.screenshot({ path: `/private/tmp/claude-501/-Volumes-Development-next-www-toastboy/1ada8965-fd52-40b5-a67b-945d5dc61aad/scratchpad/shot-${width}.png`, fullPage: true });
    await page.close();
}
await browser.close();
